-- ---------------------------------------------------------------------------
-- Repairs rate_to_eur on imported expenses, and fills fx_rates with every NBU
-- daily rate from 2020-01-01 to 2026-09-11.
--
-- The Monefy import fetched history from NBU's range endpoint, which sends no
-- CORS header — so in the browser it silently returned nothing, and every
-- imported UAH/USD row got whichever single rate was already cached. amount_eur
-- is generated from rate_to_eur, so correcting the rate corrects the euro
-- amount (and every chart) with it.
--
-- Run once in Supabase → SQL Editor. Safe to re-run. The SQL editor bypasses
-- row level security, so this touches every account's non-euro expenses — each
-- one simply gets the official rate for the day it was spent.
-- ---------------------------------------------------------------------------

begin;

-- Units per 1 EUR: uah straight from NBU, usd derived as uah_per_eur / uah_per_usd.
on conflict (day) do update set usd = excluded.usd, uah = excluded.uah, source = 'nbu';

update public.expenses e
set rate_to_eur = case e.currency when 'UAH' then r.uah else r.usd end
from public.fx_rates r
where r.day = e.spent_on
  and e.currency in ('UAH', 'USD')
  and e.rate_to_eur <> case e.currency when 'UAH' then r.uah else r.usd end;

commit;

-- What it looks like now: distinct_rates should be close to distinct_days, and
-- without_rate counts rows dated before the range above (left untouched).
select
  e.currency,
  count(*)                                   as expenses,
  count(distinct e.spent_on)                 as distinct_days,
  count(distinct e.rate_to_eur)              as distinct_rates,
  count(*) filter (where r.day is null)      as without_rate
from public.expenses e
left join public.fx_rates r on r.day = e.spent_on
where e.currency in ('UAH', 'USD')
group by e.currency;
